def com_recuo(funcao, max_tentativas=5, t0=1.0, teto=30.0,
              jitter=0.25, dormir=lambda s: None, rng=None):
    for k in range(max_tentativas):
        try:
            return funcao(), k + 1, esperas
        except ErroPermanente:
            raise                      # não repete
        except ErroTransitorio:
            if k == max_tentativas - 1:
                raise                  # esgotou
            espera = min(teto, t0 * 2 ** k) * (1 + rng.uniform(0, jitter))
            dormir(espera)             # injetável: testa sem esperar

def memoria_pesos_gb(n_params, bits):
    return n_params * bits / 8 / 1e9

def memoria_kv_gb(camadas, T, n_kv, d_cab, bytes_num=2):
    return 2 * camadas * T * n_kv * d_cab * bytes_num / 1e9

def cabe(n_params, bits, camadas, T, n_kv, d_cab, gb, margem=0.15):
    total = memoria_pesos_gb(n_params, bits) + memoria_kv_gb(
        camadas, T, n_kv, d_cab)
    return total, total <= gb * (1 - margem)

